/**
 * Organization member detail component.
 * @module organization-member-detail
 */

import { getComponentStyles, type Role } from '@auth0/universal-components-core';
import { ArrowLeft } from 'lucide-react';
import * as React from 'react';

import { GateKeeper } from '../shared/gate-keeper/gate-keeper';

import { MemberRemoveFromOrganizationModal } from '@/components/auth0/my-organization/shared/member-management/members/member-danger-zone/member-remove-from-organization-modal';
import { OrganizationMemberEditDetailsTab } from '@/components/auth0/my-organization/shared/member-management/organization-member-detail/organization-member-details-tab';
import { OrganizationMemberEditRolesTab } from '@/components/auth0/my-organization/shared/member-management/organization-member-detail/organization-member-roles-tab';
import { StyledScope } from '@/components/auth0/shared/styled-scope';
import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { useOrganizationMemberDetail } from '@/hooks/my-organization/use-member-detail';
import { useTheme } from '@/hooks/shared/use-theme';
import { useTranslator } from '@/hooks/shared/use-translator';
import { cn } from '@/lib/utils';
import { getInitials } from '@/lib/utils/my-organization/member-management/member-management-utils';
import type {
  MemberDetailHeaderProps,
  OrganizationMemberDetailProps,
  OrganizationMemberDetailViewProps,
} from '@/types/my-organization/member-management/organization-member-detail-types';

/**
 * Member detail header component.
 * @param props - Component props containing state and handlers
 * @returns The rendered header element
 */
function Header({
  member,
  styling,
  customMessages,
  handleBack,
}: MemberDetailHeaderProps): React.JSX.Element {
  const { isDarkMode } = useTheme();
  const { t } = useTranslator('member_management', customMessages);
  const currentStyles = React.useMemo(
    () => getComponentStyles(styling, isDarkMode),
    [styling, isDarkMode],
  );

  const userId = member?.user_id ?? '';
  const displayName = member?.name ?? userId;
  const initials = getInitials(displayName);

  return (
    <div className={currentStyles.classes?.['OrganizationMemberDetail-header']}>
      <Button
        variant="ghost"
        size="sm"
        className="mb-4 -ml-2 text-muted-foreground hover:text-primary"
        onClick={handleBack}
      >
        <ArrowLeft className="h-4 w-4 mr-1" />
        {t('member.detail.back_button')}
      </Button>

      <div className="flex items-center gap-4 mb-8">
        <Avatar className="h-16 w-16 shrink-0">
          <AvatarFallback className="text-xl font-semibold">{initials}</AvatarFallback>
        </Avatar>
        <div className="flex flex-col gap-1 min-w-0">
          <h1 className="text-heading font-bold text-primary truncate">{displayName}</h1>
          {userId && (
            <span className="text-sm flex items-center gap-2">
              {t('member.detail.user_id_label')}
              <Badge variant="secondary" className="w-fit font-mono text-xs">
                {userId}
              </Badge>
            </span>
          )}
        </div>
      </div>
    </div>
  );
}

/**
 * View component for organization member detail.
 * @param props - Component props containing state and handlers
 * @returns The rendered member detail view element
 */
export function OrganizationMemberDetailView(
  props: OrganizationMemberDetailViewProps,
): React.JSX.Element {
  const {
    styling,
    customMessages,
    activeTab,
    modalState,
    isRemovingFromOrganization,
    setActiveTab,
    closeModal,
    openModal,
    handleRemoveFromOrganizationConfirm,
  } = props;

  const { isDarkMode } = useTheme();
  const { t } = useTranslator('member_management', customMessages);

  const currentStyles = React.useMemo(
    () => getComponentStyles(styling, isDarkMode),
    [styling, isDarkMode],
  );

  const handleRemoveFromOrganizationClick = React.useCallback(
    () => openModal({ type: 'removeFromOrganization' }),
    [openModal],
  );

  const handleAssignRolesClick = React.useCallback(
    () => openModal({ type: 'assignRoles' }),
    [openModal],
  );

  const handleRemoveRolesClick = React.useCallback(
    (roles: Role[]) => openModal({ type: 'removeRoles', roles }),
    [openModal],
  );

  if (props.memberError) {
    return (
      <StyledScope style={currentStyles.variables}>
        <div className={currentStyles.classes?.['OrganizationMemberDetail-root']}>
          <Button
            variant="ghost"
            size="sm"
            className="mb-4 -ml-2 text-muted-foreground hover:text-primary"
            onClick={props.handleBack}
          >
            <ArrowLeft className="h-4 w-4 mr-1" />
            {t('member.detail.back_button')}
          </Button>
          <div
            className="flex flex-col items-center justify-center p-8 space-y-2"
            role="alert"
            aria-live="assertive"
          >
            <p className="text-xl text-center">{props.memberError}</p>
          </div>
        </div>
      </StyledScope>
    );
  }

  return (
    <StyledScope style={currentStyles.variables}>
      <div className={currentStyles.classes?.['OrganizationMemberDetail-root']}>
        <Header
          member={props.member}
          styling={styling}
          customMessages={customMessages}
          handleBack={props.handleBack}
        />
        <Tabs
          value={activeTab}
          onValueChange={(value) => setActiveTab(value as 'details' | 'roles')}
          className={cn('gap-8', currentStyles.classes?.['OrganizationMemberDetail-tabs'])}
        >
          <TabsList>
            <TabsTrigger value="details">{t('member.detail.tabs.details')}</TabsTrigger>
            <TabsTrigger value="roles">{t('member.detail.tabs.roles')}</TabsTrigger>
          </TabsList>

          <TabsContent
            value="details"
            className={currentStyles.classes?.['OrganizationMemberDetail-detailsTab']}
          >
            <OrganizationMemberEditDetailsTab
              member={props.member}
              customMessages={customMessages}
              isRemovingFromOrganization={isRemovingFromOrganization}
              onRemoveFromOrganizationClick={handleRemoveFromOrganizationClick}
            />
          </TabsContent>

          <TabsContent
            value="roles"
            className={currentStyles.classes?.['OrganizationMemberDetail-rolesTab']}
          >
            <OrganizationMemberEditRolesTab
              customMessages={customMessages}
              organizationName={props.organizationDisplayName}
              memberName={props.member?.name}
              selectedMember={props.member}
              memberRoles={props.memberRoles}
              searchedRoles={props.searchedRoles}
              onRoleSearch={props.onRoleSearch}
              selectedRoles={props.selectedRoles}
              isFetchingMemberRoles={props.isFetchingMemberRoles}
              removingRoleIds={props.removingRoleIds}
              isRemovingRoles={props.isRemovingRoles}
              modalState={modalState}
              isAssigningRoles={props.isAssigningRoles}
              classes={currentStyles.classes}
              style={currentStyles.variables}
              onSelectedRolesChange={props.setSelectedRoles}
              onAssignRolesClick={handleAssignRolesClick}
              onAssignRolesCancel={closeModal}
              onAssignRolesSubmit={props.handleAssignRolesSubmit}
              onRemoveRolesClick={handleRemoveRolesClick}
              onRemoveRolesCancel={props.handleRemoveRolesCancel}
              onRemoveRolesConfirm={props.handleRemoveRolesConfirm}
            />
          </TabsContent>
        </Tabs>

        <MemberRemoveFromOrganizationModal
          isOpen={modalState.type === 'removeFromOrganization'}
          isLoading={isRemovingFromOrganization}
          memberName={props.member?.name}
          memberUserId={props.member?.user_id}
          organizationName={props.organizationDisplayName}
          customMessages={customMessages}
          classes={currentStyles.classes}
          style={currentStyles.variables}
          onClose={closeModal}
          onConfirm={handleRemoveFromOrganizationConfirm}
        />
      </div>
    </StyledScope>
  );
}

/**
 * Container component for organization member detail.
 * @param props - {@link OrganizationMemberDetailProps}
 * @returns The rendered member detail container element
 */
export function OrganizationMemberDetail(props: OrganizationMemberDetailProps) {
  const {
    userId,
    onBack,
    customMessages = {},
    styling = { variables: { common: {}, light: {}, dark: {} }, classes: {} },
    removeFromOrganizationAction,
    assignRolesAction,
    removeRolesAction,
  } = props;

  const memberDetail = useOrganizationMemberDetail({
    userId,
    onBack,
    customMessages,
    removeFromOrganizationAction,
    assignRolesAction,
    removeRolesAction,
  });

  return (
    <GateKeeper isLoading={memberDetail.isLoading} styling={styling}>
      <OrganizationMemberDetailView
        {...memberDetail}
        styling={styling}
        customMessages={customMessages}
      />
    </GateKeeper>
  );
}

/**
 * Confirmation modal for removing a member from the organization.
 * @module member-remove-from-organization-modal
 * @internal
 */

import * as React from 'react';

import { Button } from '@/components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Spinner } from '@/components/ui/spinner';
import { useTranslator } from '@/hooks/shared/use-translator';
import type { MemberRemoveFromOrganizationModalProps } from '@/types/my-organization/member-management/organization-member-detail-types';

/**
 * Renders the remove from organization confirmation dialog.
 * @param props - Component props
 * @param props.classes - Custom CSS class overrides
 * @param props.style - CSS variables computed by the parent
 * @returns The rendered confirmation dialog element
 */
export function MemberRemoveFromOrganizationModal({
  isOpen,
  isLoading = false,
  memberName,
  memberUserId,
  organizationName,
  customMessages,
  classes,
  style,
  onClose,
  onConfirm,
}: MemberRemoveFromOrganizationModalProps): React.JSX.Element {
  const { t } = useTranslator('member_management', customMessages);

  const handleSubmit = React.useCallback(() => {
    onConfirm(memberUserId, memberName, organizationName);
  }, [onConfirm, memberUserId, memberName, organizationName]);

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent style={style} className={classes?.['MemberRemoveFromOrgModal-dialogContent']}>
        <DialogHeader>
          <DialogTitle className="mb-4">
            {t('member.detail.actions.remove_from_organization.modal.title', { organizationName })}
          </DialogTitle>
          <DialogDescription>
            <>
              {t.trans('member.detail.actions.remove_from_organization.modal.description', {
                components: {
                  bold: (children: string) => <strong key="memberName">{children}</strong>,
                },
                vars: { memberName },
              })}
            </>
          </DialogDescription>
        </DialogHeader>
        <DialogFooter>
          <Button variant="outline" onClick={onClose} disabled={isLoading}>
            {t('member.detail.actions.remove_from_organization.modal.cancel_button')}
          </Button>
          <Button variant="destructive" onClick={handleSubmit} disabled={isLoading}>
            {isLoading ? (
              <Spinner size="sm" />
            ) : (
              t('member.detail.actions.remove_from_organization.modal.confirm_button')
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

/**
 * Modal for assigning roles to a member.
 * @module organization-member-assign-roles-modal
 * @internal
 */

import * as React from 'react';

import { Button } from '@/components/ui/button';
import { Combobox } from '@/components/ui/combobox';
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import { useTranslator } from '@/hooks/shared/use-translator';
import type { OrganizationMemberAssignRolesModalProps } from '@/types/my-organization/member-management/organization-member-detail-types';

/**
 * Renders the assign roles dialog for selecting and assigning roles to a member.
 * @param props - Component props
 * @param props.classes - Custom CSS class overrides
 * @param props.style - CSS variables computed by the parent
 * @returns The rendered assign roles dialog element
 */
export function OrganizationMemberAssignRolesModal({
  isOpen,
  isLoading = false,
  availableRoles,
  assignedRoles,
  customMessages,
  selectedMember,
  classes,
  style,
  onClose,
  onAssign,
  onRoleSearch,
}: OrganizationMemberAssignRolesModalProps): React.JSX.Element {
  const { t } = useTranslator('member_management', customMessages);
  const [selectedRoles, setSelectedRoles] = React.useState<string[]>([]);
  const userId = selectedMember?.user_id ?? null;
  const memberRoles = selectedMember?.roles ?? assignedRoles ?? [];

  React.useEffect(() => {
    if (!isOpen) {
      setSelectedRoles([]);
      onRoleSearch?.('');
    }
  }, [isOpen, onRoleSearch]);

  const assignedRoleIds = React.useMemo(
    () => new Set(assignedRoles.map((r) => r.id)),
    [assignedRoles],
  );

  const unassignedRoles = React.useMemo(
    () => availableRoles.filter((r) => !assignedRoleIds.has(r.id)),
    [availableRoles, assignedRoleIds],
  );

  const handleOpenChange = React.useCallback(
    (open: boolean) => {
      if (!open) {
        setSelectedRoles([]);
        onClose();
      }
    },
    [onClose],
  );

  const handleSubmit = React.useCallback(() => {
    if (selectedRoles.length > 0) {
      onAssign(selectedRoles, memberRoles, userId);
    }
  }, [selectedRoles, onAssign, memberRoles, userId]);

  return (
    <Dialog open={isOpen} onOpenChange={handleOpenChange}>
      <DialogContent
        style={style}
        className={classes?.['OrganizationMemberAssignRolesModal-dialogContent']}
      >
        <DialogHeader>
          <DialogTitle className="mb-4">{t('member.detail.roles.assign_modal.title')}</DialogTitle>
        </DialogHeader>

        <div className="flex flex-col gap-3 w-full">
          {!onRoleSearch && unassignedRoles.length === 0 ? (
            <p className="text-sm text-muted-foreground">
              {t('member.detail.roles.assign_modal.no_roles_available')}
            </p>
          ) : (
            <>
              <Label>{t('member.detail.roles.assign_modal.roles_label')}</Label>
              <Combobox
                multiple
                options={unassignedRoles.map((r) => ({ value: r.id, label: r.name }))}
                value={selectedRoles}
                onChange={(val) => setSelectedRoles(Array.isArray(val) ? val : [val])}
                onInputChange={onRoleSearch}
                filterLocally={!onRoleSearch}
                placeholder={t('member.detail.roles.assign_modal.roles_placeholder')}
                notFoundMessage={t('member.detail.roles.assign_modal.no_roles_available')}
                disabled={isLoading}
                showSelectedCount
              />
            </>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={onClose} disabled={isLoading}>
            {t('member.detail.roles.assign_modal.cancel_button')}
          </Button>
          <Button onClick={handleSubmit} disabled={isLoading || selectedRoles.length === 0}>
            {t('member.detail.roles.assign_modal.submit_button')}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

/**
 * Confirmation modal for removing a role from a member.
 * @module organization-member-remove-role-modal
 * @internal
 */

import * as React from 'react';

import { Button } from '@/components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Spinner } from '@/components/ui/spinner';
import { useTranslator } from '@/hooks/shared/use-translator';
import type { OrganizationMemberRemoveRoleModalProps } from '@/types/my-organization/member-management/organization-member-detail-types';

/**
 * Renders the remove role confirmation dialog.
 * @param props - Component props
 * @param props.classes - Custom CSS class overrides
 * @param props.style - CSS variables computed by the parent
 * @returns The rendered confirmation dialog element
 */
export function OrganizationMemberRemoveRoleModal({
  isOpen,
  isLoading = false,
  roles,
  memberName,
  customMessages,
  classes,
  style,
  onClose,
  onConfirm,
}: OrganizationMemberRemoveRoleModalProps): React.JSX.Element {
  const { t } = useTranslator('member_management', customMessages);
  const isPlural = roles.length > 1;

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent
        style={style}
        className={classes?.['OrganizationMemberRemoveRoleModal-dialogContent']}
      >
        <DialogHeader>
          <DialogTitle>
            {t(
              isPlural
                ? 'member.detail.roles.remove_confirm.title_plural'
                : 'member.detail.roles.remove_confirm.title',
            )}
          </DialogTitle>
        </DialogHeader>
        <DialogDescription className="py-2">
          <>
            {t.trans('member.detail.roles.remove_confirm.description', {
              vars: { roleName: roles.map((r) => r.name).join(', '), memberName },
              components: { bold: (children: string) => <strong key="role">{children}</strong> },
            })}
          </>
        </DialogDescription>
        <DialogFooter>
          <Button variant="outline" onClick={onClose} disabled={isLoading}>
            {t('member.detail.roles.remove_confirm.cancel_button')}
          </Button>
          <Button variant="destructive" onClick={onConfirm} disabled={isLoading}>
            {isLoading ? (
              <Spinner size="sm" />
            ) : (
              t('member.detail.roles.remove_confirm.confirm_button')
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

/**
 * Member detail user details card component.
 * @module organization-member-user-details
 * @internal
 */

import * as React from 'react';

import { buildMemberDetailFields } from './utils';

import { CopyableText } from '@/components/auth0/shared/copyable-text';
import { Card } from '@/components/ui/card';
import { useTranslator } from '@/hooks/shared/use-translator';
import type { OrganizationMemberUserDetailsProps } from '@/types/my-organization/member-management/organization-member-detail-types';

/**
 * Renders the user details card for a member showing name, email, phone, and login timestamps.
 * @param props - Component props
 * @returns The rendered user details card element
 */
export function OrganizationMemberUserDetails({
  member,
  customMessages,
}: OrganizationMemberUserDetailsProps): React.JSX.Element {
  const { t } = useTranslator('member_management', customMessages);

  const fields = React.useMemo(() => buildMemberDetailFields(member, t), [member, t]);

  return (
    <div className="flex flex-col gap-2">
      <h3 className="text-base font-semibold text-primary">
        {t('member.detail.user_details.title')}
      </h3>
      <Card className="p-6">
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-14 gap-y-4">
          {fields.map((field) => (
            <div key={field.label} className="flex items-center justify-between gap-4">
              <span className="text-sm text-muted-foreground shrink-0">{field.label}</span>
              {field.copyable && field.value !== '—' ? (
                <CopyableText value={field.value} />
              ) : (
                <span className="text-sm text-primary">{field.value}</span>
              )}
            </div>
          ))}
        </div>
      </Card>
    </div>
  );
}

import type { OrgMember } from '@auth0/universal-components-core';

/**
 * Formats an ISO date string into a human-readable locale string.
 * @param dateStr - ISO date string to format
 * @returns Formatted date string, or an em dash if the input is absent
 */
export function formatDate(dateStr?: string): string {
  if (!dateStr) return '—';
  return new Date(dateStr).toLocaleString(undefined, {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
  });
}

/**
 * Builds the list of display fields for an org member's detail view.
 * @param member - The organization member whose details to display
 * @param t - Translation function used to look up field labels
 * @returns Array of label/value/copyable field descriptors
 */
export function buildMemberDetailFields(member: OrgMember, t: (key: string) => string) {
  const phoneNumber = member.phone_number ?? '';
  const firstIdentity = member.identities?.[0];
  const provider =
    firstIdentity?.provider && firstIdentity?.connection
      ? `${firstIdentity.provider}, ${firstIdentity.connection}`
      : '';

  return [
    { label: t('member.detail.user_details.name'), value: member.name ?? '—', copyable: false },
    { label: t('member.detail.user_details.email'), value: member.email ?? '—', copyable: true },
    {
      label: t('member.detail.user_details.phone_number'),
      value: phoneNumber || '—',
      copyable: !!phoneNumber,
    },
    { label: t('member.detail.user_details.provider'), value: provider || '—', copyable: false },
    {
      label: t('member.detail.user_details.created_at'),
      value: formatDate(member.created_at),
      copyable: false,
    },
    {
      label: t('member.detail.user_details.last_login'),
      value: formatDate(member.last_login),
      copyable: false,
    },
  ];
}

/**
 * Organization member edit details tab.
 * @module organization-member-details-tab
 */

import * as React from 'react';

import { OrganizationMemberUserDetails } from '@/components/auth0/my-organization/shared/member-management/members/organization-member-user-details/organization-member-user-details';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { useTranslator } from '@/hooks/shared/use-translator';
import type {
  OrganizationMemberEditDetailsTabProps,
  RemoveMemberFromOrganizationCardProps,
} from '@/types/my-organization/member-management/organization-member-detail-types';

/**
 * Card with a button to remove the member from the organization.
 * @param props - Component props containing handlers and loading state
 * @returns The rendered remove-from-org card element
 */
function RemoveMemberFromOrganizationCard({
  customMessages,
  isRemovingFromOrganization,
  onRemoveFromOrganizationClick,
}: RemoveMemberFromOrganizationCardProps): React.JSX.Element {
  const { t } = useTranslator('member_management', customMessages);

  return (
    <Card className="flex flex-row items-center justify-between gap-4 p-6">
      <div className="flex flex-col gap-1">
        <span className="text-sm font-medium text-primary">
          {t('member.detail.actions.remove_from_organization.title')}
        </span>
        <span className="text-sm text-muted-foreground">
          {t('member.detail.actions.remove_from_organization.description')}
        </span>
      </div>
      <Button
        variant="destructive"
        size="sm"
        onClick={onRemoveFromOrganizationClick}
        disabled={isRemovingFromOrganization}
        className="shrink-0"
      >
        {t('member.detail.actions.remove_from_organization.button')}
      </Button>
    </Card>
  );
}

/**
 * Details tab — user details + danger zone actions.
 * @param props - Component props
 * @returns The rendered details tab element
 */
export function OrganizationMemberEditDetailsTab(
  props: OrganizationMemberEditDetailsTabProps,
): React.JSX.Element {
  if (!props.member) {
    return <div className="flex flex-col gap-10" />;
  }

  return (
    <div className="flex flex-col gap-10">
      <OrganizationMemberUserDetails member={props.member} customMessages={props.customMessages} />
      <RemoveMemberFromOrganizationCard
        customMessages={props.customMessages}
        isRemovingFromOrganization={props.isRemovingFromOrganization}
        onRemoveFromOrganizationClick={props.onRemoveFromOrganizationClick}
      />
    </div>
  );
}

/**
 * Organization member edit roles tab.
 * @module organization-member-roles-tab
 */

import type { Role } from '@auth0/universal-components-core';
import { Plus, Trash2 } from 'lucide-react';
import * as React from 'react';

import { OrganizationMemberAssignRolesModal } from '@/components/auth0/my-organization/shared/member-management/members/organization-member-roles/organization-member-assign-roles-modal';
import { OrganizationMemberRemoveRoleModal } from '@/components/auth0/my-organization/shared/member-management/members/organization-member-roles/organization-member-remove-role-modal';
import { DataTable, type Column } from '@/components/auth0/shared/data-table';
import { Button } from '@/components/ui/button';
import { useTranslator } from '@/hooks/shared/use-translator';
import type {
  OrganizationMemberEditRolesTabProps,
  OrganizationMemberEditRolesTableProps,
  RolesTabHeaderProps,
} from '@/types/my-organization/member-management/organization-member-detail-types';

/**
 * Renders the header section of the roles tab with conditional action buttons.
 * @param props - Component props
 * @param props.selectedRoles - The currently selected roles
 * @param props.customMessages - Optional custom message overrides
 * @param props.onAssignRolesClick - Handler for the assign roles button click
 * @param props.onRemoveSelectedRoles - Handler for removing all selected roles
 * @returns The rendered roles tab header element
 */
function RolesTabHeader({
  selectedRoles,
  organizationName,
  customMessages,
  onAssignRolesClick,
  onRemoveSelectedRoles,
}: RolesTabHeaderProps): React.JSX.Element {
  const { t } = useTranslator('member_management', customMessages);

  return (
    <div className="flex items-center justify-between gap-4">
      <div className="flex flex-col gap-1">
        <h3 className="text-base font-semibold text-primary">{t('member.detail.roles.title')}</h3>
