/**
 * Generic data table component.
 * @param props - Component props.
 * @param props.data - Table data items.
 * @param props.columns - Column configurations.
 * @param props.loading - Loading state.
 * @param props.loader - Custom loader component.
 * @param props.emptyState - Empty state configuration.
 * @param props.onRowClick - Row click handler.
 * @param props.className - Additional CSS classes.
 * @param props.headerAlign - Default header alignment.
 * @returns JSX element
 */
export function DataTable<Item>({
  data,
  columns,
  loading = false,
  loader,
  emptyState,
  onRowClick,
  className,
  headerAlign = 'left',
  onSortChange,
  sortConfig,
  selectable = false,
  selectedRows,
  onSelectedRowsChange,
  getRowId,
  selectionLabels,
}: DataTableProps<Item>) {
  const isServerSideSort = !!onSortChange;
  const isControlledSelection = selectedRows !== undefined;

  const [internalSorting, setInternalSorting] = useState<SortingState>([]);
  const [internalRowSelection, setInternalRowSelection] = useState<RowSelectionState>({});

  // Convert controlled sortConfig to TanStack SortingState for header display
  const sorting: SortingState = useMemo(() => {
    if (isServerSideSort && sortConfig?.key) {
      return [{ id: sortConfig.key, desc: sortConfig.direction === 'desc' }];
    }
    return internalSorting;
  }, [isServerSideSort, sortConfig, internalSorting]);

  const rowSelection = useMemo<RowSelectionState>(() => {
    if (!selectable) return {};
    if (isControlledSelection && selectedRows) {
      if (getRowId) {
        return Object.fromEntries(selectedRows.map((row) => [getRowId(row), true]));
      }
      return Object.fromEntries(
        data.reduce<[string, boolean][]>((acc, item, idx) => {
          if (selectedRows.includes(item)) acc.push([String(idx), true]);
          return acc;
        }, []),
      );
    }
    return internalRowSelection;
  }, [selectable, isControlledSelection, selectedRows, getRowId, data, internalRowSelection]);

  const handleSortingChange = React.useCallback(
    (updater: SortingState | ((old: SortingState) => SortingState)) => {
      const newSorting = typeof updater === 'function' ? updater(sorting) : updater;

      if (isServerSideSort) {
        const sort = newSorting[0];
        if (sort) {
          onSortChange({ key: sort.id, direction: sort.desc ? 'desc' : 'asc' });
        } else {
          onSortChange({ key: null, direction: 'asc' });
        }
      } else {
        setInternalSorting(newSorting);
      }
    },
    [isServerSideSort, onSortChange, sorting],
  );

  const handleRowSelectionChange = React.useCallback(
    (updater: RowSelectionState | ((old: RowSelectionState) => RowSelectionState)) => {
      const newSelection = typeof updater === 'function' ? updater(rowSelection) : updater;
      if (!isControlledSelection) setInternalRowSelection(newSelection);
      if (onSelectedRowsChange) {
        const items = getRowId
          ? data.filter((item) => newSelection[getRowId(item)])
          : data.filter((_, idx) => newSelection[String(idx)]);
        onSelectedRowsChange(items);
      }
    },
    [rowSelection, isControlledSelection, onSelectedRowsChange, getRowId, data],
  );

  const selectionColumn = useMemo<ColumnDef<Item>>(
    () => ({
      id: '__selection__',
      enableSorting: false,
      size: 48,
      meta: {
        headerAlign: 'left' as AlignmentType,
        column: {
          type: 'actions',
          title: '',
          width: '48px',
          enableSorting: false,
          render: () => null,
        } as unknown as Column<Item>,
      },
      header: ({ table: t }) => (
        <Checkbox
          checked={
            t.getIsAllPageRowsSelected()
              ? true
              : t.getIsSomePageRowsSelected()
                ? 'indeterminate'
                : false
          }
          onCheckedChange={(checked) => t.toggleAllPageRowsSelected(!!checked)}
          aria-label={selectionLabels?.selectAll ?? DEFAULT_SELECTION_LABELS.selectAll}
          onClick={(e: React.MouseEvent) => e.stopPropagation()}
        />
      ),
      cell: ({ row }) => (
        <Checkbox
          checked={row.getIsSelected()}
          onCheckedChange={(checked) => row.toggleSelected(!!checked)}
          aria-label={
            selectionLabels?.selectRow(row.index) ?? DEFAULT_SELECTION_LABELS.selectRow(row.index)
          }
          onClick={(e: React.MouseEvent) => e.stopPropagation()}
        />
      ),
    }),
    [selectionLabels],
  );

  const tableColumns = useMemo<ColumnDef<Item>[]>(() => {
    const dataCols: ColumnDef<Item>[] = columns.map((column, index) => {
      return {
        id: column.accessorKey ? String(column.accessorKey) : `column-${index}`,
        accessorKey: column.accessorKey as string,
        header:
          typeof column.title === 'string' ? column.title : () => column.title as React.ReactNode,
        size: column.width
          ? isNaN(Number(column.width))
            ? undefined
            : Number(column.width)
          : undefined,
        enableSorting: column.enableSorting !== false && !!column.accessorKey,
        meta: {
          headerAlign: column.headerAlign || headerAlign || 'left',
          column: column,
        },

        cell: ({ getValue, row }) => {
          const value = getValue();
          const item = row.original;

          if (column.type === 'actions') {
            return <div onClick={(e) => e.stopPropagation()}>{column.render(item)}</div>;
          }

          if (column.type === 'custom') {
            return <>{column.render(item, value)}</>;
          }

          if (column.type === 'switch') {
            return renderSwitchColumn(item, value as boolean, column);
          }

          if (column.type === 'button') {
            return renderButtonColumn(item, column);
          }

          if (isEmpty(value)) {
            return null;
          }

          switch (column.type) {
            case 'text':
              return renderTextColumn(item, value, column);
            case 'date':
              return renderDateColumn(item, value as Date | string | number, column);
            case 'copy':
              return renderCopyColumn(value);
            case 'badge':
              return renderBadgeColumn(value, column);
            default:
              return <span className="text-foreground">{String(value)}</span>;
          }
        },
      };
    });
    return selectable ? [selectionColumn, ...dataCols] : dataCols;
  }, [columns, headerAlign, selectable, selectionColumn]);

  const table = useReactTable({
    data,
    columns: tableColumns,
    state: {
      sorting,
      ...(selectable && { rowSelection }),
    },
    getRowId: getRowId,
    onSortingChange: handleSortingChange,
    ...(selectable && { onRowSelectionChange: handleRowSelectionChange }),
    enableRowSelection: selectable,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: isServerSideSort ? undefined : getSortedRowModel(),
    manualSorting: isServerSideSort,
    manualPagination: true,
  });

  if (loading) {
    return (
      <div className={cn('w-full flex items-center justify-center py-8', className)}>
        {loader || <Spinner />}
      </div>
    );
  }

  return (
    <div className={cn('w-full', className)}>
      <Table>
        <TableHeader>
          {table.getHeaderGroups().map((headerGroup) => (
            <TableRow key={headerGroup.id}>
              {headerGroup.headers.map((header) => {
                const canSort = header.column.getCanSort();
                const sortDirection = header.column.getIsSorted();
                const meta = header.column.columnDef.meta as {
                  headerAlign: AlignmentType;
                  column: Column<Item>;
                };

                return (
                  <TableHead
                    key={header.id}
                    className={cn(
                      canSort && 'hover:bg-muted/50',
                      'transition-colors',
                      ALIGNMENT_CLASSES.text[meta.headerAlign],
                    )}
                    style={{
                      width: meta.column.width,
                      minWidth: meta.column.width,
                      maxWidth: meta.column.width,
                    }}
                    onClick={canSort ? header.column.getToggleSortingHandler() : undefined}
                    isSortable={canSort}
                    sortDirection={sortDirection}
                  >
                    {flexRender(header.column.columnDef.header, header.getContext())}
                  </TableHead>
                );
              })}
            </TableRow>
          ))}
        </TableHeader>
        <TableBody>
          {table.getRowModel().rows.length === 0 ? (
            <TableRow disableHover>
              <TableCell colSpan={tableColumns.length}>
                <EmptyState
                  {...(emptyState ?? {
                    title: 'No data available',
                    subtitle: 'There are no items to display.',
                  })}
                />
              </TableCell>
            </TableRow>
          ) : (
            table.getRowModel().rows.map((row) => (
              <TableRow
                key={row.id}
                className={cn(
                  onRowClick && 'cursor-pointer hover:bg-muted/50',
                  'transition-colors',
                )}
                onClick={() => onRowClick?.(row.original)}
              >
                {row.getVisibleCells().map((cell) => {
                  const meta = cell.column.columnDef.meta as {
                    column: Column<Item>;
                  };
                  return (
                    <TableCell
                      key={cell.id}
                      className="text-left"
                      style={{
                        width: meta.column.width,
                        minWidth: meta.column.width,
                        maxWidth: meta.column.width,
                      }}
                    >
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </TableCell>
                  );
                })}
              </TableRow>
            ))
          )}
        </TableBody>
      </Table>
    </div>
  );
}

/**
 * GateKeeper component for guarding content during loading, MFA step-up, and 5xx error states.
 * @module gate-keeper
 * @internal
 */

import {
  type ComponentStyling,
  getComponentStyles,
  getStatusCode,
  isMfaRequiredError,
} from '@auth0/universal-components-core';
import { RefreshCcw } from 'lucide-react';
import React, { useCallback, useMemo, useState, useEffect } from 'react';

import { StyledScope } from '@/components/auth0/shared/styled-scope';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardFooter, CardTitle } from '@/components/ui/card';
import { Spinner } from '@/components/ui/spinner';
import { useCoreClient } from '@/hooks/shared/use-core-client';
import { useTheme } from '@/hooks/shared/use-theme';
import { useTranslator } from '@/hooks/shared/use-translator';
import { useGateKeeperContext } from '@/providers/gate-keeper-context';

interface GateKeeperProps {
  styling?: ComponentStyling<Record<string, string>>;
  isLoading?: boolean;
  children: React.ReactNode;
}

/**
 * Blocking error fallback with retry button.
 * Shown for 5xx errors and dismissed MFA errors.
 *
 * @param props - Component props.
 * @param props.onRetry - Retry handler.
 * @returns Error fallback element.
 * @internal
 */
function ErrorFallback({ onRetry, isMfa }: { onRetry: () => void; isMfa?: boolean }) {
  const { t } = useTranslator('gate_keeper');
  const key = isMfa ? 'mfa_error' : 'fallback';

  return (
    <Card className="text-center">
      <CardContent className="flex flex-col items-center gap-2">
        <CardTitle>{t(`${key}.title`)}</CardTitle>
        <CardDescription>{t(`${key}.description`)}</CardDescription>
      </CardContent>
      {!isMfa && (
        <CardFooter className="justify-center">
          <Button variant="primary" size="default" onClick={onRetry}>
            <RefreshCcw className="size-4" />
            {t('fallback.retry')}
          </Button>
        </CardFooter>
      )}
    </Card>
  );
}

/**
 * Guards children from rendering during loading/error states. MFA step-up overlays
 * children without unmounting them, preserving any in-progress form state.
 * - Loading → spinner (blocks children)
 * - MFA required error → MFA step-up dialog overlaid on children
 * - 5xx error or dismissed MFA → blocking error fallback with retry
 * - No error → children
 *
 * @param props - Component props.
 * @param props.styling - Styling configuration forwarded to the styled scope.
 * @param props.isLoading - Whether content is loading.
 * @param props.children - Child elements to render on success.
 * @returns GateKeeper element.
 */
export function GateKeeper({ styling, isLoading, children }: GateKeeperProps) {
  const { error, onRetry } = useGateKeeperContext();
  const { coreClient } = useCoreClient();
  const { isDarkMode } = useTheme();
  const [isRetrying, setIsRetrying] = useState(false);

  const styles = useMemo(() => getComponentStyles(styling, isDarkMode), [styling, isDarkMode]);

  const handleRetry = useCallback(async () => {
    setIsRetrying(true);
    try {
      await onRetry?.();
    } finally {
      setIsRetrying(false);
    }
  }, [onRetry]);

  const isMfaStepUp = isMfaRequiredError(error);
  const statusCode = getStatusCode(error);
  const isSystemError = !!error && !!statusCode && (statusCode >= 500 || statusCode === 429);

  useEffect(() => {
    if (isMfaStepUp && coreClient && !coreClient.isProxyMode()) {
      console.warn(
        `🚨 [Auth0 Components Warning]: A step-up authentication (MFA) was triggered, but the interactiveErrorHandler is not configured.\n\nTo enable Universal Login redirects for MFA step-up, login required, or consent errors, please update your configuration:\n\n<Auth0Provider\n  ...\n  interactiveErrorHandler="popup"\n>\n\nFor more details, refer to the Auth0 Documentation.`,
      );
    }
  }, [isMfaStepUp, coreClient]);

  if (isLoading || isRetrying) {
    return (
      <StyledScope style={styles.variables}>
        <div className="flex items-center justify-center p-8">
          <Spinner />
        </div>
      </StyledScope>
    );
  }

  if (isSystemError || isMfaStepUp) {
    return (
      <StyledScope style={styles.variables}>
        <ErrorFallback onRetry={handleRetry} isMfa={isMfaStepUp} />
      </StyledScope>
    );
  }

  return <StyledScope style={styles.variables}>{children}</StyledScope>;
}

import * as React from 'react';

import { cn } from '@/lib/utils';

/**
 * Props for the `MiddleEllipsisText` component.
 */
export interface MiddleEllipsisTextProps {
  /**
   * Full text value to render and truncate from the middle when needed.
   */
  text: string;
  /**
   * Optional class names applied to the text container.
   */
  className?: string;
}

/**
 * Truncates text by preserving both the start and end segments and inserting
 * an ellipsis in the middle when the measured width exceeds the available width.
 *
 * @param text Full source text.
 * @param availableWidth Maximum width available for rendering in pixels.
 * @param font Canvas font shorthand used for text measurement.
 * @returns The display string and whether truncation was applied.
 */
function calculateTruncatedText(
  text: string,
  availableWidth: number,
  font: string,
): { truncated: string; isTruncated: boolean } {
  if (!text || availableWidth <= 0) {
    return { truncated: text, isTruncated: false };
  }

  // Create a canvas element for text measurement
  const canvas = document.createElement('canvas');
  const context = canvas.getContext('2d');
  if (!context) {
    return { truncated: text, isTruncated: false };
  }

  context.font = font;
  const ellipsis = '...';
  const fullWidth = context.measureText(text).width;

  // If text fits, return as-is
  if (fullWidth <= availableWidth) {
    return { truncated: text, isTruncated: false };
  }

  const ellipsisWidth = context.measureText(ellipsis).width;
  const targetWidth = availableWidth - ellipsisWidth;

  if (targetWidth <= 0) {
    return { truncated: ellipsis, isTruncated: true };
  }

  // Binary search for optimal split point
  let start = 0;
  let end = text.length;
  let bestStart = 0;
  let bestEnd = text.length;

  while (start <= end) {
    const mid = Math.floor((start + end) / 2);
    const leftPart = text.substring(0, mid);
    const rightPart = text.substring(text.length - mid);
    const combinedWidth =
      context.measureText(leftPart).width + context.measureText(rightPart).width;

    if (combinedWidth <= targetWidth) {
      bestStart = mid;
      bestEnd = text.length - mid;
      start = mid + 1;
    } else {
      end = mid - 1;
    }
  }

  const truncated = text.substring(0, bestStart) + ellipsis + text.substring(bestEnd);
  return { truncated, isTruncated: true };
}

/**
 * Renders text that truncates in the middle (`abc...xyz`) based on the
 * container width while preserving both the prefix and suffix.
 *
 * A tooltip with the original text is provided when truncation occurs.
 */
export const MiddleEllipsisText = React.memo(
  React.forwardRef<HTMLSpanElement, MiddleEllipsisTextProps>(({ text, className }, ref) => {
    const [displayText, setDisplayText] = React.useState(text);
    const [isTruncated, setIsTruncated] = React.useState(false);
    const containerRef = React.useRef<HTMLSpanElement>(null);
    const rafIdRef = React.useRef<number | null>(null);

    React.useImperativeHandle(ref, () => containerRef.current!);

    const updateTruncation = React.useCallback(() => {
      const container = containerRef.current;
      if (!container) return;

      const computedStyle = window.getComputedStyle(container);
      const font = `${computedStyle.fontSize} ${computedStyle.fontFamily}`;
      const availableWidth = container.offsetWidth;

      const { truncated, isTruncated: truncated_flag } = calculateTruncatedText(
        text,
        availableWidth,
        font,
      );

      setDisplayText(truncated);
      setIsTruncated(truncated_flag);
    }, [text]);

    // Update truncation on mount/text change and observe resize
    React.useEffect(() => {
      updateTruncation();

      const container = containerRef.current;
      let resizeObserver: ResizeObserver | null = null;

      if (container) {
        resizeObserver = new ResizeObserver(() => {
          if (rafIdRef.current !== null) {
            cancelAnimationFrame(rafIdRef.current);
          }
          rafIdRef.current = requestAnimationFrame(() => {
            updateTruncation();
          });
        });

        resizeObserver.observe(container);
      }

      return () => {
        if (rafIdRef.current !== null) {
          cancelAnimationFrame(rafIdRef.current);
          rafIdRef.current = null;
        }
        resizeObserver?.disconnect();
      };
    }, [updateTruncation]);

    return (
      <span
        ref={containerRef}
        className={cn('block min-w-0', className)}
        title={isTruncated ? text : undefined}
      >
        {displayText}
      </span>
    );
  }),
);

