};

/**
 * Toast notification types.
 * @module toast-types
 */

import type { ReactNode } from 'react';
import type { ExternalToast } from 'sonner';

/** Toast notification type. */
export type ToastType = 'success' | 'info' | 'warning' | 'error';

/** Toast position options. */
export type ToastPosition =
  | 'top-left'
  | 'top-right'
  | 'bottom-left'
  | 'bottom-right'
  | 'top-center'
  | 'bottom-center';

/** Custom toast method signature. */
export interface CustomToastMethod {
  (message: string): void;
}

/** Custom toast methods for overriding default behavior. */
export interface CustomToastMethods {
  success?: CustomToastMethod;
  error?: CustomToastMethod;
  warning?: CustomToastMethod;
  info?: CustomToastMethod;
  dismiss?: (toastId?: string) => void;
}

/** Sonner toast settings. */
export interface SonnerSettings {
  position?: ToastPosition;
  maxToasts?: number;
  duration?: number;
  dismissible?: boolean;
  closeButton?: boolean;
}

/** Toast provider configuration. */
export type ToastSettings =
  | { provider?: 'sonner'; settings?: SonnerSettings }
  | { provider: 'custom'; methods: CustomToastMethods };

/** Toast options for showToast. */
export interface ToastOptions {
  type: ToastType;
  message: string;
  className?: string;
  icon?: ReactNode;
  data?: ExternalToast;
}

/** Default toast settings. */
export const DEFAULT_TOAST_SETTINGS: ToastSettings = {
  provider: 'sonner',
  settings: {
    position: 'top-right',
    closeButton: true,
  },
} as const;

/**
 * Member management related constants for the My Organization section.
 * @internal
 */

/**
 * Maximum number of roles that can be assigned to a member in a single
 * assign/remove request.
 */
export const MAX_ROLES_PER_REQUEST = 10;

/**
 * Maximum total number of roles a member can hold.
 */
export const MAX_ROLES_PER_MEMBER = 50;

/**
 * Maximum number of roles that can be available for assignment in the system.
 * This is used to limit the number of roles fetched and displayed in the UI when assigning roles to members.
 */
export const MAX_ROLES_AVAILABLE_FOR_ASSIGNMENT = 100;

/**
