import type { DistributionChannel } from '@auth0/universal-components-core';

declare const __DISTRIBUTION__: DistributionChannel;

export const DISTRIBUTION: DistributionChannel =
  typeof __DISTRIBUTION__ !== 'undefined' ? __DISTRIBUTION__ : 'shadcn';

export const FRAMEWORK = 'react' as const;

/**
 * Tailwind CSS utility functions.
 * @module utils
 * @internal
 */

import { clsx, type ClassValue } from 'clsx';
import { extendTailwindMerge } from 'tailwind-merge';

/**
 * Without this, e.g. `cn('text-primary-foreground', 'text-heading')` drops the color class.
 * Fix: register these as their own font-size group so they no longer conflict with text-color.
 */
const customTwMerge = extendTailwindMerge({
  extend: {
    classGroups: {
      'font-size': [
        'text-page-header',
        'text-page-description',
        'text-heading',
        'text-title',
        'text-subtitle',
        'text-body',
        'text-paragraph',
        'text-label',
      ],
    },
  },
});

/**
 * Merges class names with Tailwind CSS conflict resolution.
 * @param inputs - Input values to process
 * @returns The merged class name string
 * @internal
 */
export function cn(...inputs: ClassValue[]) {
  return customTwMerge(clsx(inputs));
}

/**
 * Member management utility functions.
 * @module member-management-utils
 * @internal
 */

import {
  type EnhancedTranslationFunction,
  type MemberInvitation,
  type OrgMember,
  type Role,
} from '@auth0/universal-components-core';

import { showToast } from '@/components/auth0/shared/toast';
import {
  MAX_ROLES_PER_MEMBER,
  MAX_ROLES_PER_REQUEST,
} from '@/lib/constants/my-organization/member-management/member-management-constants';
import type { InvitationStatus } from '@/types/my-organization/member-management/organization-invitation-table-types';

/**
 * Resolves the best display name for a member.
 * @param member - The organization member.
 * @returns The member display name.
 */
export function getMemberDisplayName(member: OrgMember): string {
  const fullName = `${member.given_name ?? ''} ${member.family_name ?? ''}`.trim();

  return fullName || member.name || member.email || member.user_id || '-';
}

/**
 * Determines the status of an invitation based on `expires_at`.
 * @param invitation - The invitation to check
 * @returns The invitation status
 */
export function getInvitationStatus(invitation: MemberInvitation): InvitationStatus {
  const isExpired = invitation.expires_at && new Date(invitation.expires_at) < new Date();

  return isExpired ? 'expired' : 'pending';
}

/**
 * Formats a member's last login time as a label.
 * @param lastLogin - The member last login timestamp.
 * @param t - Translator function (namespace: `member_management`).
 * @returns A human readable relative time label.
 */
export function getRelativeLastLoginLabel(
  lastLogin: string | undefined,
  t: EnhancedTranslationFunction,
): string {
  const never = t('member.table.never', undefined, 'Never');
  const ago = t('member.table.ago', undefined, 'ago');
  const justNow = t('member.table.just_now', undefined, 'Just now');

  if (!lastLogin) {
    return never;
  }

  const lastLoginDate = new Date(lastLogin);

  if (Number.isNaN(lastLoginDate.getTime())) {
    return never;
  }

  const diffInMs = Date.now() - lastLoginDate.getTime();

  if (diffInMs < 60 * 1000) {
    return justNow;
  }

  const translateUnit = (
    count: number,
    singularKey: string,
    pluralKey: string,
    singularFallback: string,
    pluralFallback: string,
  ): string => {
    const unit =
      count === 1
        ? t(`member.table.${singularKey}`, undefined, singularFallback)
        : t(`member.table.${pluralKey}`, undefined, pluralFallback);
    return `${count} ${unit} ${ago}`;
  };

  const diffInMinutes = Math.floor(diffInMs / (60 * 1000));
  if (diffInMinutes < 60) {
    return translateUnit(diffInMinutes, 'minute', 'minutes', 'minute', 'minutes');
  }

  const diffInHours = Math.floor(diffInMinutes / 60);
  if (diffInHours < 24) {
    return translateUnit(diffInHours, 'hour', 'hours', 'hour', 'hours');
  }

  const diffInDays = Math.floor(diffInHours / 24);
  if (diffInDays < 7) {
    return translateUnit(diffInDays, 'day', 'days', 'day', 'days');
  }

  const diffInWeeks = Math.floor(diffInDays / 7);
  if (diffInWeeks < 4) {
    return translateUnit(diffInWeeks, 'week', 'weeks', 'week', 'weeks');
  }

  const diffInMonths = Math.floor(diffInDays / 30);
  if (diffInMonths < 12) {
    return translateUnit(diffInMonths, 'month', 'months', 'month', 'months');
  }

  const diffInYears = Math.floor(diffInDays / 365);
  return translateUnit(diffInYears, 'year', 'years', 'year', 'years');
}

/**
 * Returns up to 2 uppercase initials from a display name, or 'U' if the name is empty.
 * @param name - The display name to extract initials from
 * @returns Up to 2 uppercase initials, or 'U' if the name is empty
 */
export function getInitials(name?: string): string {
  const trimmed = name?.trim();
  if (!trimmed) return 'U';
  const parts = trimmed.split(/\s+/);
  const first = parts[0] ?? '';
  if (parts.length === 1) return first.charAt(0).toUpperCase();
  const last = parts[parts.length - 1] ?? '';
  return (first.charAt(0) + last.charAt(0)).toUpperCase();
}

/**
 * Validates a role assign/remove request
 * @param t - Translator function
 * @param roleIds - Role ids to assign/remove
 * @param memberRoles - Current roles of the member
 * @param assign - `true` for assignment requests
 * @returns `{ aborted: true }` when validation fails and `null` if the request may proceed.
 */
export const validateRequestRoleForMember = (
  t: EnhancedTranslationFunction,
  roleIds: string[],
  memberRoles?: Role[] | null,
  assign: boolean = false,
): { aborted: true } | null => {
  let errorKey: string | null = null;

  if (roleIds.length > MAX_ROLES_PER_REQUEST) {
    errorKey = assign
      ? 'member.error.too_many_roles_per_assignment'
      : 'member.error.too_many_roles_per_removal';
  } else if (assign) {
    const existingIds = new Set(memberRoles?.map((r) => r.id));
    const newRoleCount = roleIds.filter((id) => !existingIds.has(id)).length;
    if ((memberRoles?.length ?? 0) + newRoleCount > MAX_ROLES_PER_MEMBER) {
      errorKey = 'member.error.member_role_limit_exceeded';
    }
  }

  if (!errorKey) return null;

  showToast({ type: 'error', message: t(errorKey) });
  return { aborted: true };
};

/**
 * CSS implementation detection for telemetry.
 * @module css-detection
 * @internal
 */

import type { CssImplementation } from '@auth0/universal-components-core';

/**
 * Detects the CSS implementation being used by the application.
 *
 * Scoped CSS: imports `@auth0/universal-components-react/styles` which has
 * all styles prefixed with `.auth0-universal` selector (e.g., `.auth0-universal .sr-only`).
 *
 * Tailwind CSS: imports `@auth0/universal-components-react/tailwind` or uses
 * Tailwind directly where utilities like `.sr-only` are global.
 *
 * Detection: Check if `.sr-only` styles only apply inside `.auth0-universal` wrapper.
 * - Scoped: `.sr-only` without wrapper has no effect, with wrapper it works
 * - Tailwind: `.sr-only` works globally without needing wrapper
 *
 * @returns The detected CSS implementation ('scoped' or 'tailwind')
 * @internal
 */
export function detectCssImplementation(): CssImplementation {
  if (typeof document === 'undefined') {
    return 'unknown';
  }
  const element = document.body;
  // Create probe without .auth0-universal wrapper
  const probeWithoutWrapper = document.createElement('div');
  probeWithoutWrapper.className = 'sr-only';
  probeWithoutWrapper.style.visibility = 'hidden';
  probeWithoutWrapper.setAttribute('aria-hidden', 'true');
  element.appendChild(probeWithoutWrapper);

  const computedWithout = getComputedStyle(probeWithoutWrapper);
  // In Tailwind mode, .sr-only works globally (position: absolute)
  // In Scoped mode, .sr-only only works inside .auth0-universal wrapper
  const srOnlyWorksGlobally = computedWithout.position === 'absolute';

  element.removeChild(probeWithoutWrapper);

  return srOnlyWorksGlobally ? 'tailwind' : 'scoped';
}

/**
 * TanStack Query v4/v5 compatibility utilities.
 * @module tanstack-compat
 * @internal
 */

import type { UseMutationResult, keepPreviousData } from '@tanstack/react-query';
import * as ReactQuery from '@tanstack/react-query';

/**
 * Returns whether a mutation is in a pending/loading state, compatible with both v4 and v5.
 * In v5, `isPending` replaces `isLoading` on mutations.
 * @param mutation - The mutation result object.
 * @returns `true` if the mutation is pending or loading.
 */
export function isMutationLoading<
  T extends Pick<UseMutationResult, 'isPending'> & { isLoading?: boolean },
>(mutation: T): boolean {
  return mutation.isPending ?? mutation.isLoading ?? false;
}

type PlaceholderDataOption = { placeholderData: typeof keepPreviousData };
type LegacyKeepPreviousOption = { keepPreviousData: true };
type PreviousDataOption = PlaceholderDataOption | LegacyKeepPreviousOption;

/**
 * Reads `keepPreviousData` off the TanStack Query namespace, or returns undefined on v4.
 * @returns v5's native keepPreviousData, otherwise undefined.
 */
function getNativeKeepPreviousData(): typeof keepPreviousData | undefined {
  const key = ['keep', 'Previous', 'Data'].join('');
  return (ReactQuery as Record<string, unknown>)[key] as typeof keepPreviousData | undefined;
}

/**
 * Returns the correct query option for keeping previous data, compatible with both v4 and v5.
 * In v5, `keepPreviousData` boolean option was replaced by `placeholderData: keepPreviousData`.
 * @returns The appropriate option object to spread into a query config.
 */
export function getPreviousDataOption(): PreviousDataOption {
  const keepPreviousData = getNativeKeepPreviousData();
  if (typeof keepPreviousData === 'function') {
    return { placeholderData: keepPreviousData };
  }
  return { keepPreviousData: true };
}

/**
 * React.useId compatibility utility.
 * @module use-id-compat
 * @internal
 */

import * as React from 'react';

// The version check runs once at module load, not per render.
let idCounter = 0;

/**
 * Shim for React.useId on React 17. Generates a stable, unique ID per component
 * instance using useRef and a module-level counter.
 * @returns A stable ID string.
 */
function useIdShim(): string {
  const ref = React.useRef<string | null>(null);
  if (ref.current === null) {
    ref.current = `:r${idCounter++}:`;
  }
  return ref.current;
}

/**
 * Reads `useId` off the React namespace, or returns undefined on React 17.
 *
 * The access is intentionally computed (`React[key]`, not `React.useId`): a
 * static member access makes bundlers like webpack treat it as a named-import
 * binding and fail ESM linking against React 17 — which has no `useId` export —
 * with `ESModulesLinkingError`, even though the runtime guard never reaches it.
 * A computed key the bundler can't resolve statically sidesteps that analysis.
 * @returns React's native useId on React 18+, otherwise undefined.
 */
function getNativeUseId(): (() => string) | undefined {
  const key = ['use', 'Id'].join('');
  return (React as { useId?: () => string })[key as 'useId'];
}

const nativeUseId = getNativeUseId();

/**
 * Returns a stable, unique ID for a component instance.
 * Uses React.useId natively on React 18+, falls back to a ref-based shim on React 17.
 */
export const useId: () => string = typeof nativeUseId === 'function' ? nativeUseId : useIdShim;
